  118  // stack returns a nicely formatted stack frame, skipping skip frames.
  119  func stack(skip int) []byte {
  120  	buf := new(bytes.Buffer) // the returned data
  121  	// As we loop, we open files and read them. These variables record the currently
  122  	// loaded file.
  123  	var (
  124  		nLine    string
  125  		lastFile string
  126  		err      error
  127  	)
  128  	for i := skip; ; i++ { // Skip the expected number of frames
  129  		pc, file, line, ok := runtime.Caller(i)
  130  		if !ok {
  131  			break
  132  		}
  133  		// Print this much at least.  If we can't find the source, it won't show.
  134  		fmt.Fprintf(buf, "%s:%d (0x%x)\n", file, line, pc)
  135  		if file != lastFile {
  136  			nLine, err = readNthLine(file, line-1)
  137  			if err != nil {
  138  				continue
  139  			}
  140  			lastFile = file
  141  		}
  142  		fmt.Fprintf(buf, "\t%s: %s\n", function(pc), cmp.Or(nLine, dunno))
  143  	}
  144  	return buf.Bytes()
  145  }
