  147  // readNthLine reads the nth line from the file.
  148  // It returns the trimmed content of the line if found,
  149  // or an empty string if the line doesn't exist.
  150  // If there's an error opening the file, it returns the error.
  151  func readNthLine(file string, n int) (string, error) {
  152  	if n < 0 {
  153  		return "", nil
  154  	}
  155  
  156  	f, err := os.Open(file)
  157  	if err != nil {
  158  		return "", err
  159  	}
  160  	defer f.Close()
  161  
  162  	scanner := bufio.NewScanner(f)
  163  	for i := 0; i < n; i++ {
  164  		if !scanner.Scan() {
  165  			return "", nil
  166  		}
  167  	}
  168  
  169  	if scanner.Scan() {
  170  		return strings.TrimSpace(scanner.Text()), nil
  171  	}
  172  
  173  	return "", nil
  174  }
