  176  // function returns, if possible, the name of the function containing the PC.
  177  func function(pc uintptr) string {
  178  	fn := runtime.FuncForPC(pc)
  179  	if fn == nil {
  180  		return dunno
  181  	}
  182  	name := fn.Name()
  183  	// The name includes the path name to the package, which is unnecessary
  184  	// since the file name is already included.  Plus, it has center dots.
  185  	// That is, we see
  186  	//	runtime/debug.*T·ptrmethod
  187  	// and want
  188  	//	*T.ptrmethod
  189  	// Also the package path might contain dot (e.g. code.google.com/...),
  190  	// so first eliminate the path prefix
  191  	if lastSlash := strings.LastIndexByte(name, '/'); lastSlash >= 0 {
  192  		name = name[lastSlash+1:]
  193  	}
  194  	if period := strings.IndexByte(name, '.'); period >= 0 {
  195  		name = name[period+1:]
  196  	}
  197  	name = strings.ReplaceAll(name, "·", ".")
  198  	return name
  199  }
